import{_ as t,c as e,a2 as _,o as a}from"./chunks/framework.CqbvlPrP.js";const m=JSON.parse('{"title":"交易的核心是概率吗？","description":"","frontmatter":{},"headers":[],"relativePath":"stock/交易认知/交易的核心一定是盈亏比，而不是胜率。本质更是概率.md","filePath":"stock/交易认知/交易的核心一定是盈亏比，而不是胜率。本质更是概率.md"}'),r={name:"stock/交易认知/交易的核心一定是盈亏比，而不是胜率。本质更是概率.md"};function o(s,p,n,c,i,d){return a(),e("div",null,p[0]||(p[0]=[_('<h1 id="交易的核心是概率吗" tabindex="-1">交易的核心是概率吗？ <a class="header-anchor" href="#交易的核心是概率吗" aria-label="Permalink to &quot;交易的核心是概率吗？&quot;">​</a></h1><p>交易的核心一定是盈亏比，而不是胜率。本质更是概率</p><p>一笔足够赚钱的单子，可以覆盖掉你多笔的小止损。</p><p>期货本质是试错交易，在试错中寻找正确的方向。</p><p>盈亏比对应的背后是趋势交易策略，而胜率对应的则是短线交易策略。</p><p>趋势交易一般胜率大概在30~40左右。意思10笔单子，可能6~7笔都止损掉了，剩余的几笔持仓赚大钱。</p><p>短线呢，则要求更高，快进快出，底层逻辑胜率就必须高，要不然你快进快出的同时，一方面手续费是一个大头，你的亏损更是一个大头。</p><p>如果你短线连续亏损几次，控制不好手，你心里的可能更多是想赢回来，此时你就会变成一个赌徒，而不是在做投机交易。</p><p>短线有做的好的，我认为一万个里边有两到三个长期赚钱的就不错了，但是我觉得普通人很难做好。</p><p>包括我，我看一下盘面，总感觉有很多机会再等着做，我只要一投入，我原本制定好的机会，都会被盘面波动而受到影响，从而管不住手。</p><p>短线的结局，我认为是赚小亏大，爆仓出局。</p><p>那么做趋势呢，就相对好做很多，不需要你去盯盘，正常你该干嘛干嘛，期货本身的波动影响不了你。</p><p>做趋势难的地方不在于你对品种的多空判断，以及关键点位的入场，以及具有关键意义的止损点。</p><p>做趋势难得是坚守规则，与时间做朋友，敢于持仓，敢于面对盈利的回撤。</p><p>底层逻辑则是对一个人心态、格局的考验。</p><p>做趋势不需要误打误撞，是有明确的判断标准。</p><p>我用的是28日均线，我把它理解为趋势多空反转的重要分水岭。</p><p>28日线上开多，28日线下开空。</p><p>一句话，大道至简，最简单的方法，去应对最复杂的市场。</p><p>当然也有很多人用均线，例如大部分用20日均线，非常有效，但是参考的人太多!</p><p>还有很多人使用60日均线，他也是重要的多空分水岭，但是60日滞后比较严重，等你准备参与的时候，行情已经走了一大截，所以我不参考60日。</p><p>我用的28日，则是在其中，中和了两者的趋势特点。</p><p>想做趋势交易，则需要明白一下几点</p><p>1.判断品种多空的能力 （基本能力）</p><p>2.寻找合适的入场点位 （学会等待，不随意下单）</p><p>3.清晰的止损逻辑 （避免大亏的前提）</p><p>4.清晰的止盈规则 （避免利润大幅回撤）</p><p>5.大格局持仓能力 （与普通散户操作拉开的重要能力）</p><p>6.大周期交易（降低交易频率，间接降低止损概率）</p><hr><p>综上所述，形成小赚、小亏、大赚、不大亏的交易系统，</p><p>有了交易系统，需要通过模拟盘三个月以上的训练，给自己定个目标，10万做到20万这样</p><p>还得是严格遵守交易系统的！</p><hr><p>通过训练，形成交易认知，有了认知</p><p>你上实盘才不会慌张，才不会不自信，有了认知，你就可以赚到认知之内的钱！</p><p>如果没有模拟盘的认知，贸然上实盘，大概率止损几次，你也就放弃了！</p>',37)]))}const f=t(r,[["render",o]]);export{m as __pageData,f as default};
